{"CommandLine":"$bytes = [System.IO.File]::ReadAllBytes("C:\Program Files\Allen & Heath\SQ MixPad 1.6.1\SQ MixPad.exe")
$text = [System.Text.Encoding]::ASCII.GetString($bytes)
foreach ($kw in @("recallDefaultShow", "saveCurrentShowToWorkingFolder", "WorkingShowPath", "peqDriver", "compDriver", "preampDriver", "gateDriver")) {
    $idx = 0
    Write-Host "=== $kw ==="
    while (($idx = $text.IndexOf($kw, $idx)) -ge 0) {
        $start = [Math]::Max(0, $idx - 200)
        $len = [Math]::Min(600, $text.Length - $start)
        $sub = $text.Substring($start, $len) -replace "[^\x20-\x7E]+", " | "
        Write-Host "At $idx : $sub"
        $idx += $kw.Length
    }
}","WaitMsBeforeAsync":5000,"toolSummary":"Find QML code for showManager and channel drivers in SQ MixPad.exe"}
